(function (global) {
    "use strict";
    let serial = 0;
    const chapterCounts = {};
    function q(chapterId, difficulty, en, hi, choices, answer, why, whyHi) {
        serial += 1;
        chapterCounts[chapterId] = (chapterCounts[chapterId] || 0) + 1;
        const offset = (serial - 1) % 4;
        const questionId = "M4-" + String(serial).padStart(3, "0");
        const chapter = global.OLEVEL_CATALOG[3].chapters.find(function (entry) { return entry.id === chapterId; });
        const topicIndex = (chapterCounts[chapterId] - 1) % chapter.topics.length;
        const options = choices.map(function (choice, index) { return { id: questionId + "-O" + (index + 1), en: choice[0], hi: choice[1] }; });
        const ordered = options.slice(offset).concat(options.slice(0, offset));
        return { id: questionId, moduleId: "M4-R5.1", chapterId: chapterId, topicId: chapterId + "-topic-" + (topicIndex + 1), topic: chapter.topics[topicIndex], difficulty: difficulty, questionEnglish: en, questionHindi: hi, options: ordered, correctOptionId: options[answer].id, explanationEnglish: why, explanationHindi: whyHi, sourceType: "Original Practice", source: { name: "ZeroKB original practice", year: null } };
    }
    global.OLEVEL_BANKS = global.OLEVEL_BANKS || {};
    global.OLEVEL_BANKS.m4 = [
        q("iot-intro", "Moderate", "Which description best distinguishes an Internet of Things system from a stand-alone sensor?", "कौन-सा वर्णन Internet of Things प्रणाली को अकेले sensor से सबसे अच्छी तरह अलग करता है?", [["Connected devices sense or act and exchange data with services or other devices", "जुड़े उपकरण sensing या action करते हैं और services या अन्य उपकरणों से डेटा साझा करते हैं"], ["A sensor has a plastic enclosure", "Sensor का enclosure प्लास्टिक का होता है"], ["Every device must contain a web browser", "हर उपकरण में web browser होना चाहिए"], ["A device records data but can never communicate", "उपकरण डेटा रिकॉर्ड करता है पर संचार नहीं कर सकता"]], 0, "IoT combines identifiable devices, sensing or actuation, connectivity and data-driven services.", "IoT में पहचाने जा सकने वाले उपकरण, sensing या actuation, connectivity और data-आधारित services जुड़ते हैं।"),
        q("iot-intro", "Hard", "A safety controller must react to a local temperature limit even when internet access is unavailable. Which design choice best supports this requirement?", "सुरक्षा नियंत्रक को इंटरनेट उपलब्ध न होने पर भी स्थानीय तापमान सीमा पर प्रतिक्रिया करनी है। कौन-सा डिज़ाइन इसका सर्वोत्तम समर्थन करता है?", [["Perform the critical threshold decision locally at the edge", "महत्वपूर्ण threshold निर्णय स्थानीय edge पर लें"], ["Send every sample to a remote cloud and wait for a reply", "हर sample दूरस्थ cloud पर भेजकर उत्तर की प्रतीक्षा करें"], ["Disable the sensor when the network drops", "नेटवर्क टूटने पर sensor बंद करें"], ["Use a public dashboard as the only controller", "केवल public dashboard को controller बनाएँ"]], 0, "Local edge processing reduces dependence on network availability and can lower response latency for critical actions.", "स्थानीय edge processing नेटवर्क उपलब्धता पर निर्भरता घटाती है और महत्वपूर्ण कार्रवाई का विलंब कम कर सकती है।"),

        q("things-connections", "Moderate", "A device sends a reading with a timestamp, unit and device identifier. Why are these fields useful in addition to the numeric reading?", "उपकरण reading के साथ timestamp, unit और device identifier भेजता है। केवल संख्यात्मक reading की तुलना में ये fields क्यों उपयोगी हैं?", [["They provide context to interpret, locate and compare the observation", "वे observation को समझने, पहचानने और तुलना करने का संदर्भ देते हैं"], ["They automatically encrypt the network", "वे नेटवर्क स्वतः encrypt करते हैं"], ["They replace the need for calibration", "वे calibration की आवश्यकता हटाते हैं"], ["They guarantee the reading is correct", "वे reading सही होने की गारंटी देते हैं"]], 0, "Metadata identifies the source, time and measurement scale, but it does not itself prove sensor accuracy.", "Metadata स्रोत, समय और मापन इकाई पहचानता है, पर स्वयं sensor की सटीकता सिद्ध नहीं करता।"),
        q("things-connections", "Hard", "A deployment has thousands of low-power devices and changing network addresses. Which device-management practice improves reliable identification?", "तैनाती में हजारों low-power उपकरण और बदलते network addresses हैं। कौन-सी device-management पद्धति विश्वसनीय पहचान बढ़ाती है?", [["Assign stable device identities independent of temporary network addresses", "अस्थायी network addresses से स्वतंत्र स्थिर device पहचान दें"], ["Use the current IP address as the only permanent identity", "वर्तमान IP address को ही स्थायी पहचान बनाएँ"], ["Identify devices only by their color", "उपकरणों की पहचान केवल रंग से करें"], ["Reuse one credential and identifier for every device", "हर उपकरण के लिए एक ही credential और पहचान दोहराएँ"]], 0, "A stable logical identity survives address changes and enables per-device management and audit.", "स्थिर logical पहचान address बदलने पर भी बनी रहती है और प्रति-उपकरण प्रबंधन तथा audit सक्षम करती है।"),

        q("sensors-actuators", "Moderate", "A temperature sensor produces an analog voltage, but a microcontroller reads digital values. What component commonly converts between these representations?", "Temperature sensor analog voltage देता है लेकिन microcontroller digital मान पढ़ता है। इन निरूपणों के बीच सामान्यतः कौन-सा घटक रूपांतरण करता है?", [["Analog-to-digital converter", "Analog-to-digital converter"], ["Digital-to-analog converter only", "केवल Digital-to-analog converter"], ["Relay coil", "Relay coil"], ["Ethernet switch", "Ethernet switch"]], 0, "An ADC samples an analog signal and represents it as a digital value for processing.", "ADC analog signal का sampling करके processing के लिए digital value बनाता है।"),
        q("sensors-actuators", "Hard", "A pump is switched on whenever a noisy sensor reading crosses a threshold, causing rapid on/off cycling. Which control improvement most directly reduces this behavior?", "शोरयुक्त sensor reading threshold पार करते ही pump चालू होता है, जिससे तेज़ on/off cycling होती है। कौन-सा नियंत्रण सुधार इसे सीधे घटाता है?", [["Use hysteresis with separate turn-on and turn-off thresholds", "अलग turn-on और turn-off thresholds के साथ hysteresis उपयोग करें"], ["Increase the sampling frequency without filtering", "बिना filtering sampling frequency बढ़ाएँ"], ["Remove the actuator feedback state", "actuator की feedback state हटाएँ"], ["Convert the reading to a device name", "reading को device name में बदलें"]], 0, "Hysteresis separates activation and deactivation thresholds, preventing small fluctuations near one boundary from toggling the actuator.", "Hysteresis चालू और बंद thresholds अलग रखता है, जिससे सीमा के पास छोटे उतार-चढ़ाव actuator को बार-बार toggle नहीं करते।"),

        q("iot-communication", "Moderate", "Many IoT clients send small telemetry messages to a broker and subscribe to selected topics. Which messaging model does this describe?", "कई IoT clients broker को छोटे telemetry संदेश भेजते हैं और चुने हुए topics subscribe करते हैं। यह कौन-सा messaging model है?", [["Publish/subscribe", "Publish/subscribe"], ["Single shared-memory process", "एकल shared-memory process"], ["Point-to-point file printing", "Point-to-point file printing"], ["Circuit-switched voice only", "केवल circuit-switched voice"]], 0, "In publish/subscribe, publishers send messages to topics and a broker distributes them to subscribers.", "Publish/subscribe में publishers topics पर संदेश भेजते हैं और broker उन्हें subscribers तक पहुँचाता है।"),
        q("iot-communication", "Hard", "A battery-powered sensor reports once every several minutes and can tolerate delayed delivery. Which communication strategy can reduce radio energy use?", "Battery-powered sensor कई मिनट में एक बार report करता है और विलंबित delivery सह सकता है। Radio ऊर्जा उपयोग घटाने की कौन-सी रणनीति मदद कर सकती है?", [["Batch or buffer readings and transmit periodically with a low-power duty cycle", "Readings को batch या buffer करके low-power duty cycle में समय-समय पर भेजें"], ["Keep the radio continuously active for immediate delivery", "तुरंत delivery के लिए radio लगातार सक्रिय रखें"], ["Resend every packet continuously even after acknowledgement", "acknowledgement के बाद भी हर packet लगातार फिर भेजें"], ["Increase transmit power to maximum at all times", "हर समय transmit power अधिकतम रखें"]], 0, "Reducing radio wake time through periodic transmission can save battery when the application permits delay.", "यदि application विलंब सह सकती है, तो समय-समय पर transmission से radio सक्रिय समय घटाकर battery बचती है।"),

        q("iot-platforms", "Moderate", "An IoT platform stores device telemetry and presents trends on dashboards. Which additional capability helps an application react automatically to a threshold?", "IoT platform device telemetry संग्रहित कर dashboard पर trends दिखाता है। Threshold पर application को स्वतः प्रतिक्रिया देने में कौन-सी अतिरिक्त क्षमता मदद करती है?", [["A rule or event-processing engine", "Rule या event-processing engine"], ["A larger display font", "बड़ा display font"], ["A static image gallery", "स्थिर image gallery"], ["A device enclosure label", "device enclosure label"]], 0, "Rules evaluate incoming events or measurements and can trigger alerts or actions when conditions are met.", "Rules आने वाले events या measurements का मूल्यांकन करते हैं और शर्त पूरी होने पर alerts या actions चला सकते हैं।"),
        q("iot-platforms", "Hard", "A plant must continue a basic control loop during a temporary cloud outage while still uploading summaries later. Which architecture fits best?", "Cloud अस्थायी रूप से बंद होने पर भी संयंत्र को बुनियादी control loop चलाना है और बाद में summaries upload करनी हैं। कौन-सी architecture उपयुक्त है?", [["Local edge control with store-and-forward cloud synchronization", "Store-and-forward cloud synchronization के साथ स्थानीय edge control"], ["Cloud-only control with no local fallback", "बिना स्थानीय fallback वाला cloud-only control"], ["Disable all sensing until cloud recovery", "Cloud ठीक होने तक सभी sensing बंद करें"], ["Send control commands by public social post", "Public social post से control commands भेजें"]], 0, "Edge control maintains local operation; buffered data can synchronize when connectivity returns.", "Edge control स्थानीय संचालन जारी रखता है; connectivity लौटने पर buffered डेटा synchronize हो सकता है।"),

        q("iot-security", "Moderate", "A fleet contains devices shipped with the same default password. What is the strongest immediate deployment improvement?", "एक fleet के सभी उपकरण समान default password के साथ भेजे गए हैं। तैनाती में सबसे महत्वपूर्ण तत्काल सुधार क्या है?", [["Replace defaults with unique credentials and restrict access", "Default हटाकर अद्वितीय credentials रखें और पहुँच सीमित करें"], ["Publish the password in the user manual", "Password को user manual में प्रकाशित करें"], ["Allow anonymous remote administration", "Anonymous remote administration की अनुमति दें"], ["Disable device updates", "Device updates बंद करें"]], 0, "Unique credentials limit the impact of one exposed device and restricted access reduces attack surface.", "अद्वितीय credentials एक उपकरण के उजागर होने का प्रभाव सीमित करते हैं और सीमित पहुँच attack surface घटाती है।"),
        q("iot-security", "Hard", "An IoT product will receive security fixes for several years. Which lifecycle capability is essential for deploying those fixes safely?", "IoT उत्पाद को कई वर्षों तक security fixes मिलने हैं। उन सुधारों को सुरक्षित रूप से लागू करने के लिए कौन-सी lifecycle क्षमता आवश्यक है?", [["Authenticated, integrity-checked firmware update mechanism", "प्रमाणित और integrity-checked firmware update तंत्र"], ["Unverified executable files sent over an open channel", "खुले माध्यम से भेजी गई असत्यापित executable फाइलें"], ["A permanent shared administrator password", "स्थायी साझा administrator password"], ["A hardware reset that removes network isolation", "ऐसा hardware reset जो network isolation हटाए"]], 0, "Authenticating update sources and verifying integrity help prevent unauthorized or corrupted firmware installation.", "Update स्रोत प्रमाणित करना और integrity जाँचना अनधिकृत या दूषित firmware स्थापना रोकने में मदद करता है।"),

        q("iot-applications", "Moderate", "A farm waters a field only when measured soil moisture is below a configured threshold. What application pattern is being used?", "एक खेत में पानी तभी दिया जाता है जब मापी गई मिट्टी की नमी निर्धारित threshold से कम हो। कौन-सा application pattern उपयोग हो रहा है?", [["Sensor-driven closed-loop control", "Sensor-आधारित closed-loop control"], ["Manual batch image editing", "Manual batch image editing"], ["One-way broadcast with no measurement", "Measurement के बिना one-way broadcast"], ["Offline file compression", "Offline file compression"]], 0, "The sensor measurement informs an actuator decision, forming a feedback-based control loop.", "Sensor measurement actuator निर्णय को सूचित करता है और feedback-आधारित control loop बनाता है।"),
        q("iot-applications", "Hard", "A remote health-monitoring device detects an abnormal reading. Which design best balances useful alerting with responsible handling of personal data?", "दूरस्थ स्वास्थ्य निगरानी उपकरण असामान्य reading पहचानता है। व्यक्तिगत डेटा के जिम्मेदार उपयोग और उपयोगी alert के बीच संतुलन के लिए कौन-सा डिज़ाइन बेहतर है?", [["Send the minimum necessary protected data to authorized recipients and define escalation rules", "न्यूनतम आवश्यक सुरक्षित डेटा अधिकृत प्राप्तकर्ताओं को भेजें और escalation नियम तय करें"], ["Broadcast the patient's full record to all nearby devices", "रोगी का पूरा रिकॉर्ड आसपास के सभी उपकरणों में broadcast करें"], ["Store data publicly without access control", "बिना access control डेटा सार्वजनिक रूप से रखें"], ["Disable alerts to avoid processing personal data", "व्यक्तिगत डेटा processing से बचने के लिए alerts बंद करें"]], 0, "Data minimization, access control and defined escalation preserve privacy while routing actionable alerts.", "Data minimization, access control और तय escalation गोपनीयता रखते हुए उपयोगी alerts पहुँचाते हैं।"),
        q("iot-intro", "Easy", "A sensor network connects many field devices to a cloud service through one local aggregation point that can translate protocols. What role does that point serve?", "Sensor network कई field devices को protocol translate कर सकने वाले एक local aggregation point के माध्यम से cloud service से जोड़ता है। उस point की भूमिका क्या है?", [["IoT gateway", "IoT gateway"], ["Actuator load", "Actuator load"], ["Sensor calibration constant", "Sensor calibration constant"], ["End-user dashboard", "End-user dashboard"]], 0, "A gateway commonly aggregates device traffic and bridges local device networks to upstream services.", "Gateway सामान्यतः device traffic aggregate करता है और local device networks को upstream services से जोड़ता है।"),
        q("things-connections", "Hard", "A newly installed device should join a managed deployment without sharing a fleet-wide secret. Which provisioning approach is safer?", "नया device fleet-wide secret साझा किए बिना managed deployment में जुड़ना चाहिए। कौन-सी provisioning पद्धति अधिक सुरक्षित है?", [["Provision a unique device credential and verify its identity before granting access", "Unique device credential दें और access से पहले उसकी पहचान सत्यापित करें"], ["Use the same permanent password on every device", "हर device पर समान स्थायी password रखें"], ["Allow any device with the correct network name", "सही network name वाले हर device को अनुमति दें"], ["Publish the private key with device documentation", "Private key को device documentation के साथ प्रकाशित करें"]], 0, "Unique credentials and identity verification limit the effect of one compromised device.", "अद्वितीय credentials और पहचान सत्यापन एक compromised device के प्रभाव को सीमित करते हैं।"),
        q("sensors-actuators", "Moderate", "A digital temperature sensor reports a value that is consistently offset from a trusted reference. What action should be considered before changing the application threshold?", "Digital temperature sensor की reading विश्वसनीय reference से लगातार offset है। Application threshold बदलने से पहले क्या विचार करना चाहिए?", [["Check sensor calibration and measurement conditions", "Sensor calibration और measurement conditions जाँचें"], ["Increase network packet size", "Network packet size बढ़ाएँ"], ["Change the device identifier", "Device identifier बदलें"], ["Increase dashboard refresh rate only", "केवल dashboard refresh rate बढ़ाएँ"]], 0, "A systematic offset may arise from calibration or placement; changing the control threshold can mask the measurement fault.", "Systematic offset calibration या placement से हो सकता है; control threshold बदलना measurement fault छिपा सकता है।"),
        q("iot-communication", "Hard", "A client publishes telemetry to a broker and needs confirmation that the broker accepted the message. Which protocol feature is relevant in MQTT?", "Client broker पर telemetry publish करता है और उसे पुष्टि चाहिए कि broker ने संदेश स्वीकार किया। MQTT की कौन-सी सुविधा संबंधित है?", [["Quality of Service delivery level", "Quality of Service delivery level"], ["HTML form validation", "HTML form validation"], ["IP address subnet mask", "IP address subnet mask"], ["Sensor analog gain", "Sensor analog gain"]], 0, "MQTT QoS levels define delivery assurance behavior between a client and broker.", "MQTT QoS levels client और broker के बीच delivery assurance व्यवहार निर्धारित करते हैं।"),
        q("iot-platforms", "Moderate", "A dashboard shows no new readings although the device still has network connectivity. Which first diagnostic comparison can isolate the fault boundary?", "Device में network connectivity है, फिर भी dashboard पर नई readings नहीं दिखतीं। कौन-सी पहली तुलना fault boundary अलग कर सकती है?", [["Check whether recent messages reach the platform ingestion endpoint before investigating dashboard queries", "Dashboard query जाँचने से पहले देखें कि नए संदेश platform ingestion endpoint तक पहुँच रहे हैं या नहीं"], ["Replace every sensor immediately", "तुरंत हर sensor बदलें"], ["Change all device IDs at once", "एक साथ सभी device IDs बदलें"], ["Disable authentication on the broker", "Broker पर authentication बंद करें"]], 0, "Comparing ingestion with dashboard data distinguishes transport/ingestion failures from presentation/query issues.", "Ingestion और dashboard data की तुलना transport/ingestion समस्या को presentation/query समस्या से अलग करती है।"),
        q("iot-security", "Moderate", "A device no longer receives vendor security fixes and has a known exploitable service exposed to the internet. Which response best reduces risk?", "एक device को vendor security fixes नहीं मिलते और उसकी ज्ञात exploitable service इंटरनेट पर खुली है। जोखिम घटाने का बेहतर कदम क्या है?", [["Isolate or retire it and restrict reachable services according to the support plan", "Support plan के अनुसार उसे isolate या retire करें और reachable services सीमित करें"], ["Keep it exposed because its password is unique", "Unique password होने के कारण उसे exposed रखें"], ["Disable monitoring to reduce alerts", "Alerts घटाने के लिए monitoring बंद करें"], ["Forward all inbound ports to the device", "सभी inbound ports device को forward करें"]], 0, "An unsupported vulnerable device should be isolated or retired; a unique password alone does not fix exposed software flaws.", "Unsupported vulnerable device को isolate या retire करना चाहिए; unique password exposed software flaw को ठीक नहीं करता।"),
        q("iot-applications", "Hard", "A farm compares moisture readings from two fields with different soil types. Which data practice makes the comparison more meaningful?", "एक खेत अलग-अलग soil types वाले दो fields की moisture readings की तुलना करता है। तुलना को अधिक अर्थपूर्ण बनाने के लिए कौन-सी data practice उपयोगी है?", [["Record sensor placement and soil context, and calibrate readings before comparing thresholds", "Sensor placement और soil context दर्ज करें तथा thresholds की तुलना से पहले readings calibrate करें"], ["Assume equal raw readings imply equal water needs", "मान लें समान raw readings का अर्थ समान जल आवश्यकता है"], ["Remove timestamps to simplify the dataset", "Dataset सरल करने के लिए timestamps हटाएँ"], ["Average readings from both fields before storing them", "Store करने से पहले दोनों fields की readings average करें"]], 0, "Measurement context and calibration matter because soil properties and sensor placement affect interpretation.", "Measurement context और calibration आवश्यक हैं क्योंकि soil गुण और sensor placement व्याख्या को प्रभावित करते हैं।"),

        q("iot-intro", "Moderate", "A city wants equipment from different vendors to exchange observations using a shared data format. Which system property most directly supports this goal?", "एक शहर अलग-अलग vendors के उपकरणों से साझा data format द्वारा observations का आदान-प्रदान चाहता है। कौन-सा system गुण इस लक्ष्य को सबसे सीधे समर्थन देता है?", [["Interoperability through agreed interfaces and data representations", "सहमत interfaces और data representations के माध्यम से interoperability"], ["Keeping every device permanently offline", "हर device को स्थायी रूप से offline रखना"], ["Using a unique incompatible format for each device", "हर device के लिए अलग असंगत format उपयोग करना"], ["Increasing sensor enclosure size", "Sensor enclosure का आकार बढ़ाना"]], 0, "Interoperable interfaces and data representations allow heterogeneous components to work together.", "Interoperable interfaces और data representations अलग-अलग components को साथ काम करने देते हैं।", "Expected Practice"),
        q("iot-intro", "Moderate", "A remote monitoring service has intermittent connectivity. Which requirement should be included so short outages do not erase observations?", "Remote monitoring service में connectivity रुक-रुककर उपलब्ध है। छोटे outage से observations न खोएँ, इसके लिए कौन-सी आवश्यकता शामिल करनी चाहिए?", [["Local buffering with a defined retention and synchronization policy", "निर्धारित retention और synchronization नीति के साथ local buffering"], ["Dependence on a continuous connection for every sample", "हर sample के लिए लगातार connection पर निर्भरता"], ["Discarding readings whenever the link is slow", "Link धीमा होने पर readings छोड़ देना"], ["Using a larger dashboard font", "Dashboard का font बड़ा करना"]], 0, "Buffering retains measurements during a temporary outage, while a synchronization policy defines recovery behavior.", "Buffering अस्थायी outage के दौरान measurements सुरक्षित रखता है और synchronization नीति recovery व्यवहार तय करती है।", "Expected Practice"),
        q("iot-intro", "Moderate", "A system has many device types and services that are updated independently. Which architectural practice helps limit the effect of one component changing?", "एक system में कई device प्रकार और independently update होने वाली services हैं। एक component के बदलाव का असर सीमित करने में कौन-सी architectural practice मदद करती है?", [["Use modular components with documented, stable interfaces", "Documented और स्थिर interfaces वाले modular components उपयोग करें"], ["Allow every component to access every other component's internal state", "हर component को अन्य सभी components की internal state तक पहुँच दें"], ["Combine all functions into one indivisible program", "सभी functions को एक अविभाज्य program में जोड़ें"], ["Remove version information from interfaces", "Interfaces से version जानकारी हटाएँ"]], 0, "Modularity and stable interfaces reduce coupling and make independently managed components easier to evolve.", "Modularity और स्थिर interfaces coupling घटाते हैं और independently managed components का विकास आसान बनाते हैं।", "Expected Practice"),
        q("iot-intro", "Moderate", "A building system must serve more floors over time without redesigning every sensor. Which quality should guide the architecture?", "Building system को समय के साथ अधिक floors में सेवा देनी है, बिना हर sensor को फिर से design किए। Architecture में किस गुण को प्राथमिकता देनी चाहिए?", [["Scalability through repeatable device onboarding and service capacity", "दोहराने योग्य device onboarding और service capacity के माध्यम से scalability"], ["A fixed device limit with no expansion path", "विस्तार के बिना निश्चित device सीमा"], ["Manual processing of every reading", "हर reading की manual processing"], ["A single shared identity for all sensors", "सभी sensors के लिए एक साझा identity"]], 0, "A scalable architecture can accommodate more devices and workload without replacing its basic design.", "Scalable architecture मूल design बदले बिना अधिक devices और workload संभाल सकता है।", "Expected Practice"),
        q("iot-intro", "Moderate", "An IoT alarm is required to notify staff within two seconds even when a cloud round trip is slow. Which design decision best meets the latency requirement?", "IoT alarm को cloud round trip धीमा होने पर भी दो सेकंड में staff को सूचित करना है। कौन-सा design निर्णय latency आवश्यकता बेहतर पूरी करता है?", [["Place time-critical detection and notification logic near the monitored system", "समय-संवेदनशील detection और notification logic को monitored system के निकट रखें"], ["Send each sample to a distant service and wait for analysis", "हर sample दूरस्थ service पर भेजकर analysis की प्रतीक्षा करें"], ["Increase historical data retention only", "केवल historical data retention बढ़ाएँ"], ["Refresh a remote dashboard less often", "Remote dashboard को कम बार refresh करें"]], 0, "Processing close to the source avoids dependence on wide-area round-trip delay for time-critical action.", "Source के पास processing करने से समय-संवेदनशील कार्रवाई wide-area round-trip delay पर निर्भर नहीं रहती।", "Expected Practice"),
        q("iot-intro", "Hard", "An industrial monitor must preserve local safety actions, continue recording during outages and later provide an auditable history. Which architecture best combines these needs?", "Industrial monitor को local safety actions बनाए रखने, outage के दौरान recording जारी रखने और बाद में auditable history देने की आवश्यकता है। कौन-सी architecture इन आवश्यकताओं को सर्वोत्तम जोड़ती है?", [["Local edge rules and durable buffering with authenticated synchronization to a central service", "Central service के साथ authenticated synchronization हेतु local edge rules और durable buffering"], ["Cloud-only rules with immediate deletion of unsent readings", "केवल cloud rules और न भेजी गई readings को तुरंत मिटाना"], ["A public dashboard as the sole data store and controller", "Public dashboard को एकमात्र data store और controller बनाना"], ["A gateway that disables local control whenever it loses internet access", "ऐसा gateway जो internet न होने पर local control बंद कर दे"]], 0, "Edge decision-making and durable buffering sustain operation; authenticated synchronization supports later central audit.", "Edge निर्णय और durable buffering संचालन बनाए रखते हैं; authenticated synchronization बाद में central audit में मदद करता है।", "Expected Practice"),
        q("iot-intro", "Hard", "A deployment needs to handle both time-critical alarms and large historical analytics efficiently. Which division of work is most appropriate?", "Deployment को time-critical alarms और बड़े historical analytics दोनों कुशलता से संभालने हैं। काम का कौन-सा विभाजन उपयुक्त है?", [["Run low-latency control near devices and aggregate long-term analysis in cloud services", "कम latency वाला control devices के पास चलाएँ और दीर्घकालिक analysis cloud services में aggregate करें"], ["Send every actuator decision to a batch report", "हर actuator निर्णय को batch report में भेजें"], ["Perform all historical analysis independently on each sensor", "सारा historical analysis हर sensor पर अलग-अलग करें"], ["Use the cloud only to set physical sensor voltage", "Physical sensor voltage तय करने के लिए ही cloud उपयोग करें"]], 0, "Edge processing suits fast local response, while cloud resources can combine data across devices for broader analysis.", "Edge processing तेज़ local response के लिए उपयुक्त है, जबकि cloud अनेक devices के data का व्यापक analysis कर सकता है।", "Expected Practice"),
        q("iot-intro", "Hard", "A system's sensor, network and application teams use different units and incompatible message structures. Which corrective measure addresses the root architectural problem?", "एक system की sensor, network और application teams अलग-अलग units और असंगत message structures उपयोग करती हैं। कौन-सा सुधार मूल architectural समस्या को हल करता है?", [["Define shared data schemas, units and interface contracts across layers", "सभी layers में साझा data schemas, units और interface contracts निर्धारित करें"], ["Increase radio transmit power", "Radio transmit power बढ़ाएँ"], ["Store readings without metadata", "Metadata के बिना readings संग्रहित करें"], ["Add more dashboards without changing message definitions", "Message definitions बदले बिना और dashboards जोड़ें"]], 0, "Cross-layer contracts make exchanged measurements interpretable and reduce integration mismatches.", "Cross-layer contracts साझा measurements को समझने योग्य बनाते हैं और integration mismatch घटाते हैं।", "Expected Practice"),

        q("things-connections", "Moderate", "A sensor reports a temperature as 23.5 but omits whether the unit is Celsius or Fahrenheit. What should the telemetry schema add?", "Sensor तापमान 23.5 भेजता है पर Celsius या Fahrenheit unit नहीं बताता। Telemetry schema में क्या जोड़ना चाहिए?", [["An explicit measurement unit", "स्पष्ट measurement unit"], ["A second device password", "दूसरा device password"], ["A dashboard color preference", "Dashboard color preference"], ["A network retransmission counter only", "केवल network retransmission counter"]], 0, "An explicit unit prevents consumers from interpreting the same numeric value on different scales.", "स्पष्ट unit उपभोक्ताओं को एक ही numeric value को अलग-अलग scales पर गलत समझने से बचाता है।", "Expected Practice"),
        q("things-connections", "Moderate", "Two devices use private IP addresses that can be reassigned after reboot. What is the best way for an application to address a particular device over time?", "दो devices ऐसे private IP addresses उपयोग करते हैं जो reboot के बाद बदल सकते हैं। Application को किसी device को समय के साथ कैसे संबोधित करना चाहिए?", [["Resolve a stable device identity through a managed registry or naming service", "Managed registry या naming service से स्थिर device identity resolve करें"], ["Treat the current private IP as permanent identity", "वर्तमान private IP को स्थायी identity मानें"], ["Identify it by the order in which packets arrive", "Packets आने के क्रम से पहचानें"], ["Use the sensor's latest reading as its address", "Sensor की नवीनतम reading को उसका address बनाएँ"]], 0, "A stable logical name or registry mapping remains useful when a network locator changes.", "Network locator बदलने पर भी स्थिर logical नाम या registry mapping उपयोगी रहती है।", "Expected Practice"),
        q("things-connections", "Moderate", "A telemetry service receives duplicate packets after a sender retries during a lost acknowledgement. What should the receiver use to avoid counting the same event twice?", "Acknowledgement खोने पर sender retry करता है और telemetry service को duplicate packets मिलते हैं। एक ही घटना दो बार गिनने से बचने के लिए receiver क्या उपयोग करे?", [["A unique event identifier or sequence number with duplicate detection", "Duplicate detection के साथ unique event identifier या sequence number"], ["A longer device display name", "लंबा device display name"], ["A new IP address for every retry", "हर retry के लिए नया IP address"], ["A larger analog-to-digital converter", "बड़ा analog-to-digital converter"]], 0, "Event identifiers let the receiver recognize retransmitted observations and process them idempotently.", "Event identifiers receiver को दोबारा भेजे observations पहचानने और उन्हें idempotently process करने देते हैं।", "Expected Practice"),
        q("things-connections", "Moderate", "A data service ingests measurements from meters that publish at different rates. Which metadata is essential for placing those samples correctly on a time series?", "एक data service अलग-अलग दर से publish करने वाले meters की measurements लेती है। Samples को time series में सही रखने के लिए कौन-सा metadata आवश्यक है?", [["A timestamp with a defined time basis", "परिभाषित time basis वाला timestamp"], ["The dashboard's background color", "Dashboard का background color"], ["A shared administrator password", "साझा administrator password"], ["The number of user manuals printed", "छपे हुए user manuals की संख्या"]], 0, "Timestamps with a known time basis support ordering and correlation of observations across devices.", "ज्ञात time basis वाले timestamps अलग-अलग devices की observations को क्रमबद्ध और correlate करते हैं।", "Expected Practice"),
        q("things-connections", "Moderate", "A building has battery devices that sleep for most of the day. How can a management service deliver configuration changes without assuming they are always reachable?", "Building में battery devices दिन के अधिकांश समय sleep करते हैं। Management service यह माने बिना configuration changes कैसे दे सकती है कि वे हमेशा reachable हैं?", [["Queue versioned changes and deliver them when each device next checks in", "Versioned changes queue करें और device के अगली बार check-in पर पहुँचाएँ"], ["Require every sleeping device to keep its radio continuously on", "हर sleeping device का radio लगातार चालू रखना अनिवार्य करें"], ["Erase local settings whenever the device sleeps", "Device sleep होते ही local settings मिटा दें"], ["Send changes only to a dashboard browser", "Changes केवल dashboard browser को भेजें"]], 0, "Queued, versioned configuration accommodates intermittent connectivity and lets devices apply changes at check-in.", "Queued, versioned configuration रुक-रुककर connectivity को संभालती है और device check-in पर changes लागू करती है।", "Expected Practice"),
        q("things-connections", "Hard", "A fleet operator must distinguish a device's long-lived identity from its changing Wi-Fi address and also revoke one compromised device. Which design best supports both tasks?", "Fleet operator को device की स्थायी identity को बदलते Wi-Fi address से अलग करना है और compromised device को revoke भी करना है। कौन-सा design दोनों कार्य बेहतर करता है?", [["Give each device a unique managed identity and credential that can be individually revoked", "हर device को अलग managed identity और credential दें जिसे individually revoke किया जा सके"], ["Use one fleet-wide identifier and credential as the address", "Address के रूप में पूरी fleet की एक identity और credential उपयोग करें"], ["Use the Wi-Fi address as an unchangeable identity", "Wi-Fi address को न बदलने वाली identity मानें"], ["Assign identity based on the last telemetry value", "अंतिम telemetry value के आधार पर identity दें"]], 0, "A unique logical identity survives address changes, and per-device credentials permit targeted revocation.", "अलग logical identity address बदलने पर बनी रहती है और per-device credentials लक्षित revocation देते हैं।", "Expected Practice"),
        q("things-connections", "Hard", "A monitoring platform combines data from meters whose manufacturers label the same measurement differently. What is the most robust ingestion strategy?", "Monitoring platform ऐसे meters का data जोड़ता है जिनके manufacturers एक ही measurement को अलग नाम देते हैं। सबसे मजबूत ingestion strategy क्या है?", [["Validate and map incoming payloads into a canonical schema with units and provenance", "Incoming payloads को validate करके units और provenance सहित canonical schema में map करें"], ["Assume field names have identical meanings across manufacturers", "मान लें सभी manufacturers में field names का अर्थ समान है"], ["Drop units and retain only raw numbers", "Units हटाकर केवल raw numbers रखें"], ["Merge every reading into one unlabelled average", "हर reading को एक unlabelled average में मिला दें"]], 0, "Canonical validation and mapping reconcile vendor formats while retaining measurement meaning and origin.", "Canonical validation और mapping vendor formats में सामंजस्य रखते हुए measurement का अर्थ और स्रोत बनाए रखते हैं।", "Expected Practice"),
        q("things-connections", "Hard", "A remote installation loses its gateway intermittently, and readings must remain attributable and in order after reconnection. Which device behavior is most useful?", "Remote installation का gateway रुक-रुककर खो जाता है और reconnect होने पर readings का स्रोत और क्रम बनाए रखना है। Device का कौन-सा व्यवहार सबसे उपयोगी है?", [["Persist timestamped, sequenced readings locally and forward them after reconnection", "Timestamp और sequence वाली readings local रूप से सुरक्षित करें और reconnect होने पर forward करें"], ["Replace all unsent readings with the latest value", "सभी न भेजी readings को नवीनतम value से बदल दें"], ["Reset the sequence whenever connectivity drops", "Connectivity टूटते ही sequence reset करें"], ["Store readings without device or time context", "Device या time context के बिना readings संग्रहित करें"]], 0, "Persistent, sequenced telemetry preserves provenance and ordering across temporary network interruptions.", "Persistent, sequenced telemetry अस्थायी network interruption के दौरान provenance और क्रम सुरक्षित रखती है।", "Expected Practice"),

        q("sensors-actuators", "Moderate", "An ADC maps an input range into 256 distinct digital levels. What is the main measurement effect of increasing the number of levels, assuming the same input range?", "ADC input range को 256 अलग digital levels में बदलता है। समान input range मानते हुए levels बढ़ाने का मुख्य measurement प्रभाव क्या है?", [["Finer quantization steps can represent smaller input changes", "Finer quantization steps छोटे input बदलाव दर्शा सकते हैं"], ["The sensor no longer needs a power supply", "Sensor को power supply की आवश्यकता नहीं रहती"], ["The actuator becomes a wireless transmitter", "Actuator wireless transmitter बन जाता है"], ["The analog input is automatically calibrated", "Analog input स्वतः calibrated हो जाता है"]], 0, "More quantization levels divide the same range into smaller steps, though they do not by themselves correct sensor error.", "अधिक quantization levels समान range को छोटे steps में बाँटते हैं, हालांकि वे sensor error स्वयं ठीक नहीं करते।", "Expected Practice"),
        q("sensors-actuators", "Moderate", "A light sensor is sampled too slowly while a lamp flickers rapidly. Which problem may make the recorded brightness misleading?", "Lamp तेज़ी से flicker करता है पर light sensor बहुत धीरे sample होता है। कौन-सी समस्या दर्ज brightness को भ्रामक बना सकती है?", [["Aliasing from sampling below the signal's variation rate", "Signal के variation rate से कम sampling के कारण aliasing"], ["A unique device identity", "Unique device identity"], ["A broker's publish/subscribe topic", "Broker का publish/subscribe topic"], ["A firmware signature", "Firmware signature"]], 0, "Insufficient sampling can miss rapid changes or represent them as a misleading slower pattern.", "अपर्याप्त sampling तेज़ बदलाव छोड़ सकती है या उन्हें भ्रामक धीमे pattern के रूप में दिखा सकती है।", "Expected Practice"),
        q("sensors-actuators", "Moderate", "A microcontroller needs to vary a motor's average power using a digital output pin. Which common technique provides this control?", "Microcontroller को digital output pin से motor की average power बदलनी है। कौन-सी सामान्य तकनीक यह नियंत्रण देती है?", [["Pulse-width modulation", "Pulse-width modulation"], ["A static device identifier", "Static device identifier"], ["An IP subnet mask", "IP subnet mask"], ["A dashboard query", "Dashboard query"]], 0, "PWM varies the fraction of each cycle spent in the active state, controlling average delivered power.", "PWM प्रत्येक cycle में active रहने का अनुपात बदलता है और औसत दी गई power नियंत्रित करता है।", "Expected Practice"),
        q("sensors-actuators", "Moderate", "A relay coil is controlled by a microcontroller pin that cannot supply the coil's current. What interface is commonly added?", "Microcontroller pin relay coil का आवश्यक current नहीं दे सकता। सामान्यतः कौन-सा interface जोड़ा जाता है?", [["A transistor or driver stage rated for the coil load", "Coil load के लिए rated transistor या driver stage"], ["A second temperature sensor", "दूसरा temperature sensor"], ["A stronger Wi-Fi password", "अधिक मजबूत Wi-Fi password"], ["A digital-to-analog converter in every case", "हर स्थिति में digital-to-analog converter"]], 0, "A suitable driver lets a low-current logic output switch a higher-current load safely.", "उपयुक्त driver कम-current logic output को अधिक-current load सुरक्षित रूप से switch करने देता है।", "Expected Practice"),
        q("sensors-actuators", "Moderate", "A flow sensor provides one pulse for each fixed volume of liquid. How should software estimate the total delivered volume?", "Flow sensor तरल की प्रत्येक निश्चित मात्रा पर एक pulse देता है। Software कुल दी गई मात्रा का अनुमान कैसे लगाए?", [["Count pulses and multiply by the calibrated volume per pulse", "Pulses गिनकर प्रति pulse calibrated volume से गुणा करें"], ["Measure the network signal strength", "Network signal strength मापें"], ["Average the device identifiers", "Device identifiers का average लें"], ["Convert the pulse count to a timestamp only", "Pulse count को केवल timestamp में बदलें"]], 0, "A calibrated pulse-to-volume factor converts counted events into an estimate of the physical quantity.", "Calibrated pulse-to-volume factor गिने हुए events को physical quantity के अनुमान में बदलता है।", "Expected Practice"),
        q("sensors-actuators", "Hard", "A level sensor is specified to resolve 1 mm changes, but installation noise varies by 5 mm. What is the most defensible conclusion?", "Level sensor 1 mm बदलाव resolve करने के लिए specified है, लेकिन installation noise 5 mm बदलता है। सबसे उचित निष्कर्ष क्या है?", [["The system's effective measurement uncertainty is dominated by noise, so finer display precision is not evidence of 1 mm accuracy", "System की प्रभावी measurement uncertainty पर noise हावी है; अधिक display precision 1 mm accuracy का प्रमाण नहीं है"], ["Displaying more decimal places removes the noise", "अधिक decimal places दिखाने से noise हटता है"], ["The sensor resolution guarantees 1 mm accuracy in all installations", "Sensor resolution हर installation में 1 mm accuracy की गारंटी देता है"], ["Increasing the network range improves the sensor's physical accuracy", "Network range बढ़ाने से sensor की physical accuracy सुधरती है"]], 0, "Resolution describes distinguishable increments; installation noise still limits the measurement's useful certainty.", "Resolution अलग पहचाने जा सकने वाले increments बताता है; installation noise measurement की उपयोगी निश्चितता सीमित करता है।", "Expected Practice"),
        q("sensors-actuators", "Hard", "A controller drives a heater from an unisolated mains circuit, while its microcontroller uses low-voltage logic. Which design principle is essential?", "Controller heater को unisolated mains circuit से चलाता है जबकि microcontroller low-voltage logic उपयोग करता है। कौन-सा design principle आवश्यक है?", [["Use a properly rated, isolated interface and maintain required electrical separation", "उचित rating वाला isolated interface उपयोग करें और आवश्यक electrical separation बनाए रखें"], ["Connect the mains load directly to a logic pin", "Mains load को सीधे logic pin से जोड़ें"], ["Remove protective isolation to reduce latency", "Latency घटाने के लिए protective isolation हटाएँ"], ["Use a network gateway as the only electrical protection", "Network gateway को ही electrical protection मानें"]], 0, "Isolation and correctly rated switching protect low-voltage control electronics from hazardous load circuitry.", "Isolation और सही rating वाली switching low-voltage control electronics को खतरनाक load circuitry से बचाती है।", "Expected Practice"),
        q("sensors-actuators", "Hard", "A valve's command signal indicates open, but the measured flow stays zero. Which control strategy best detects and handles this discrepancy?", "Valve का command signal open बताता है, लेकिन measured flow शून्य रहता है। यह अंतर पहचानने और संभालने की कौन-सी control strategy बेहतर है?", [["Compare commanded state with independent process feedback, then raise a fault or enter a safe state", "Commanded state की independent process feedback से तुलना करें, फिर fault उठाएँ या safe state अपनाएँ"], ["Assume the actuator succeeded whenever a command was sent", "Command भेजते ही मान लें actuator सफल हुआ"], ["Suppress the flow measurement", "Flow measurement दबा दें"], ["Repeat the command indefinitely without monitoring", "Monitoring के बिना command अनिश्चितकाल तक दोहराएँ"]], 0, "Feedback verifies the physical outcome rather than assuming that a command changed the process.", "Feedback केवल command भेजने की धारणा के बजाय physical outcome की पुष्टि करता है।", "Expected Practice"),

        q("iot-communication", "Moderate", "A constrained battery sensor exchanges short request-and-response messages with a nearby service. Which protocol family is designed for this style of constrained web communication?", "Constrained battery sensor पास की service से छोटे request-and-response messages का आदान-प्रदान करता है। इस constrained web communication के लिए कौन-सा protocol family बनाया गया है?", [["CoAP", "CoAP"], ["SMTP", "SMTP"], ["HDMI", "HDMI"], ["FTP for large media transfer", "बड़े media transfer के लिए FTP"]], 0, "CoAP is a lightweight web transfer protocol suited to constrained devices and networks.", "CoAP constrained devices और networks के लिए उपयुक्त lightweight web transfer protocol है।", "Expected Practice"),
        q("iot-communication", "Moderate", "A sensor network spans several rooms, and intermediate powered nodes can relay messages for distant nodes. Which topology can exploit this capability?", "Sensor network कई कमरों में फैला है और बीच के powered nodes दूर के nodes के संदेश relay कर सकते हैं। कौन-सी topology इस क्षमता का उपयोग कर सकती है?", [["Mesh topology", "Mesh topology"], ["A single isolated point with no links", "बिना links वाला एक अकेला point"], ["A one-way broadcast with no forwarding", "Forwarding के बिना one-way broadcast"], ["A direct cable from every node to a remote cloud", "हर node से दूरस्थ cloud तक सीधी cable"]], 0, "Mesh links can provide multi-hop paths when intermediate nodes participate in forwarding.", "Mesh links में intermediate nodes forwarding करें तो multi-hop paths मिल सकते हैं।", "Expected Practice"),
        q("iot-communication", "Moderate", "A wearable sends small readings to a phone in the same room and must minimize pairing complexity and energy use. Which link is a reasonable candidate?", "Wearable उसी कमरे में phone को छोटी readings भेजता है और pairing की जटिलता तथा energy उपयोग कम रखना है। कौन-सा link उपयुक्त विकल्प है?", [["Bluetooth Low Energy", "Bluetooth Low Energy"], ["Long-distance satellite uplink", "Long-distance satellite uplink"], ["A wired industrial fieldbus across the room", "कमरे में फैला wired industrial fieldbus"], ["High-power cellular streaming", "High-power cellular streaming"]], 0, "Bluetooth Low Energy is commonly suited to short-range, low-energy links between peripherals and nearby devices.", "Bluetooth Low Energy सामान्यतः peripherals और पास के devices के बीच short-range, low-energy link के लिए उपयुक्त है।", "Expected Practice"),
        q("iot-communication", "Moderate", "A sensor network must reach a distant site where there is no local Wi-Fi, and messages are infrequent. Which design factor should be compared when considering cellular connectivity?", "Sensor network को दूरस्थ site तक पहुँचना है जहाँ local Wi-Fi नहीं है और messages कम आते हैं। Cellular connectivity पर विचार करते समय किस factor की तुलना करनी चाहिए?", [["Coverage, subscription cost, energy use and required data volume", "Coverage, subscription cost, energy use और आवश्यक data volume"], ["Dashboard font size and screen resolution", "Dashboard font size और screen resolution"], ["Only the sensor enclosure color", "केवल sensor enclosure का रंग"], ["Whether the device has an HDMI port", "क्या device में HDMI port है"]], 0, "Cellular can provide wide-area reach, but coverage, recurring cost and power draw must fit the use case.", "Cellular wide-area reach देता है, पर coverage, recurring cost और power draw उपयोग के अनुरूप होने चाहिए।", "Expected Practice"),
        q("iot-communication", "Moderate", "A site has heavy radio interference but permits a cable route to the controller. Which link choice most directly avoids the radio interference?", "Site पर radio interference अधिक है लेकिन controller तक cable route संभव है। कौन-सा link radio interference से सीधे बचता है?", [["A suitable wired communication link", "उपयुक्त wired communication link"], ["A different wireless channel without testing", "बिना परीक्षण दूसरा wireless channel"], ["Maximum wireless transmit power in all locations", "हर स्थान पर अधिकतम wireless transmit power"], ["A dashboard refresh setting", "Dashboard refresh setting"]], 0, "A wired link avoids the affected radio channel, provided installation and distance requirements are met.", "Installation और दूरी की आवश्यकताएँ पूरी हों तो wired link प्रभावित radio channel से बचता है।", "Expected Practice"),
        q("iot-communication", "Hard", "A building's battery sensors must reach a gateway through concrete walls; traffic is sparse, and several mains-powered repeaters are available. Which network design best balances reach and battery life?", "Building के battery sensors को concrete walls के पार gateway तक पहुँचना है; traffic कम है और कई mains-powered repeaters उपलब्ध हैं। कौन-सा network design reach और battery life में संतुलन रखता है?", [["Use a low-power multi-hop network with mains-powered nodes forwarding traffic", "Mains-powered nodes से traffic forward कराकर low-power multi-hop network उपयोग करें"], ["Keep every battery sensor at maximum transmit power continuously", "हर battery sensor को लगातार maximum transmit power पर रखें"], ["Require each sensor to stream video to the gateway", "हर sensor से gateway को video stream कराएँ"], ["Disable forwarding so every sensor uses a direct long-range link", "Forwarding बंद कर हर sensor से direct long-range link अनिवार्य करें"]], 0, "Forwarding-capable powered nodes can extend coverage without forcing battery sensors to transmit at high power.", "Forwarding-capable powered nodes coverage बढ़ा सकते हैं और battery sensors को high power पर transmit करने से बचाते हैं।", "Expected Practice"),
        q("iot-communication", "Hard", "An alarm packet must arrive reliably, but retransmitting a large telemetry batch is costly. Which communication policy is most appropriate?", "Alarm packet विश्वसनीय रूप से पहुँचना चाहिए, लेकिन बड़ा telemetry batch दोबारा भेजना महँगा है। कौन-सी communication policy उपयुक्त है?", [["Choose delivery assurance per message class, using stronger acknowledgement/retry for alarms and controlled batching for routine data", "हर message class के लिए delivery assurance चुनें: alarms में मजबूत acknowledgement/retry और routine data में नियंत्रित batching"], ["Apply maximum retransmissions to every packet regardless of urgency", "Urgency की परवाह किए बिना हर packet पर अधिकतम retransmission करें"], ["Disable acknowledgements for alarms and telemetry alike", "Alarms और telemetry दोनों के acknowledgements बंद करें"], ["Use one continuous high-rate stream for all messages", "सभी messages के लिए एक continuous high-rate stream उपयोग करें"]], 0, "Different traffic classes need different reliability and energy trade-offs; critical alarms merit stronger delivery handling.", "अलग traffic classes को reliability और energy में अलग संतुलन चाहिए; critical alarms को अधिक मजबूत delivery handling चाहिए।", "Expected Practice"),
        q("iot-communication", "Hard", "An engineer proposes a wireless protocol solely because it has the highest advertised data rate, although devices send tiny messages and run on coin cells. What is the best evaluation response?", "Engineer सबसे अधिक advertised data rate के कारण wireless protocol चुनता है, जबकि devices छोटे messages भेजते हैं और coin cells पर चलते हैं। सर्वोत्तम मूल्यांकन क्या होगा?", [["Compare actual throughput needs with energy per message, sleep support, range and deployment conditions", "वास्तविक throughput आवश्यकता की energy per message, sleep support, range और deployment conditions से तुलना करें"], ["Select it immediately because peak data rate determines battery life", "तुरंत वही चुनें क्योंकि peak data rate battery life तय करती है"], ["Ignore range because all radios have identical coverage", "Range की अनदेखी करें क्योंकि सभी radios की coverage समान है"], ["Choose the protocol with the largest connector", "सबसे बड़ा connector वाला protocol चुनें"]], 0, "Peak throughput alone does not capture the power, range and operating-pattern trade-offs of an IoT link.", "केवल peak throughput IoT link के power, range और operating-pattern trade-offs नहीं बताता।", "Expected Practice"),

        q("iot-platforms", "Moderate", "A platform receives a device's readings but cannot interpret which field is temperature or what units it uses. Which integration artifact would prevent this ambiguity?", "Platform को device readings मिलती हैं लेकिन temperature field या units का अर्थ स्पष्ट नहीं है। कौन-सा integration artifact यह अस्पष्टता रोकेगा?", [["A versioned payload schema describing fields, types and units", "Fields, types और units बताने वाला versioned payload schema"], ["A higher dashboard refresh frequency", "अधिक dashboard refresh frequency"], ["A longer Wi-Fi password", "लंबा Wi-Fi password"], ["An actuator connected to each sensor", "हर sensor से जुड़ा actuator"]], 0, "A schema documents payload meaning and lets ingestion validate compatible versions.", "Schema payload का अर्थ बताता है और ingestion को compatible versions validate करने देता है।", "Expected Practice"),
        q("iot-platforms", "Moderate", "A dashboard must show a useful trend from readings that arrive at irregular intervals. Which transformation is appropriate before plotting?", "Irregular intervals पर आने वाली readings से dashboard को उपयोगी trend दिखाना है। Plot करने से पहले कौन-सा transformation उपयुक्त है?", [["Validate timestamps and aggregate or resample values into defined time windows", "Timestamps validate करके values को निर्धारित time windows में aggregate या resample करें"], ["Sort by device name and discard timestamps", "Device name से sort करके timestamps हटा दें"], ["Treat every reading as if it arrived at equal intervals", "हर reading को समान interval पर आया मानें"], ["Replace measurements with connection status", "Measurements को connection status से बदलें"]], 0, "Time-window aggregation handles irregular sampling explicitly and makes chart intervals interpretable.", "Time-window aggregation irregular sampling को स्पष्ट रूप से संभालता है और chart intervals समझने योग्य बनाता है।", "Expected Practice"),
        q("iot-platforms", "Moderate", "An application should notify an operator once when a machine enters an abnormal state, rather than sending repeated alerts for every sample. What rule behavior is useful?", "Machine abnormal state में जाए तो application को हर sample पर repeated alert के बजाय एक बार operator को सूचित करना है। कौन-सा rule behavior उपयोगी है?", [["Trigger on a state transition and apply a defined alert cooldown or reset condition", "State transition पर trigger करें और निर्धारित alert cooldown या reset condition लागू करें"], ["Send an alert for every unchanged sample forever", "हर अपरिवर्तित sample पर हमेशा alert भेजें"], ["Ignore state and alert on device identity only", "State छोड़कर केवल device identity पर alert करें"], ["Disable event timestamps", "Event timestamps बंद करें"]], 0, "Transition-based rules and explicit reset/cooldown logic reduce alert storms while preserving meaningful events.", "Transition-आधारित rules और स्पष्ट reset/cooldown logic उपयोगी घटनाएँ रखते हुए alert storms घटाते हैं।", "Expected Practice"),
        q("iot-platforms", "Moderate", "A prototype works on a developer's laptop but must be installed across many gateways. Which deployment practice improves repeatability?", "Prototype developer के laptop पर चलता है लेकिन कई gateways पर install करना है। कौन-सी deployment practice दोहराने योग्य deployment सुधारती है?", [["Package dependencies and configuration with a documented, repeatable release process", "Dependencies और configuration को documented, repeatable release process के साथ package करें"], ["Rely on undocumented manual steps unique to one laptop", "एक laptop के undocumented manual steps पर निर्भर रहें"], ["Copy credentials into source code", "Credentials को source code में copy करें"], ["Change application settings independently on every gateway", "हर gateway पर application settings अलग-अलग बदलें"]], 0, "A reproducible package and release process reduces configuration drift and installation errors.", "Reproducible package और release process configuration drift तथा installation errors घटाता है।", "Expected Practice"),
        q("iot-platforms", "Moderate", "An operator needs to compare today's energy use with last month's readings. Which platform capability is essential beyond a live dashboard?", "Operator को आज की energy use की पिछले महीने की readings से तुलना करनी है। Live dashboard के अतिरिक्त कौन-सी platform capability आवश्यक है?", [["Time-series storage with retention and query support", "Retention और query support वाला time-series storage"], ["A one-time local LED indicator", "एक बार चलने वाला local LED indicator"], ["A device radio with no data store", "Data store के बिना device radio"], ["A rule that deletes each reading after display", "हर reading दिखाने के बाद मिटाने वाला rule"]], 0, "Historical comparison requires retained, timestamped measurements that can be queried over the requested period.", "ऐसी ऐतिहासिक तुलना के लिए retained, timestamped measurements चाहिए जिन्हें माँगी गई अवधि में query किया जा सके।", "Expected Practice"),
        q("iot-platforms", "Hard", "A control rule evaluates a sensor sample twice after a service restart and could dispense a dose twice. Which application safeguard is most important?", "Service restart के बाद control rule sensor sample को दो बार evaluate कर सकता है और dose दो बार दे सकता है। कौन-सा application safeguard सबसे महत्वपूर्ण है?", [["Make command processing idempotent using unique event or action identifiers and record completion state", "Unique event या action identifiers और completion state द्वारा command processing को idempotent बनाएँ"], ["Retry every action without retaining a state record", "State record रखे बिना हर action retry करें"], ["Remove the actuator's dose limit", "Actuator की dose limit हटाएँ"], ["Use a chart color to mark the second command", "दूसरे command को chart color से चिह्नित करें"]], 0, "Idempotency and durable action state prevent duplicate processing from causing repeated physical effects.", "Idempotency और durable action state duplicate processing से बार-बार physical effect होने से रोकते हैं।", "Expected Practice"),
        q("iot-platforms", "Hard", "A new analytics release may change how a production application interprets telemetry. How should the change be introduced to reduce operational risk?", "नया analytics release production application में telemetry की व्याख्या बदल सकता है। Operational risk घटाने के लिए बदलाव कैसे लाएँ?", [["Test against representative data, deploy to a limited cohort, monitor results and retain rollback capability", "Representative data पर test करें, सीमित cohort में deploy करें, परिणाम monitor करें और rollback क्षमता रखें"], ["Replace all running instances simultaneously with no validation", "बिना validation सभी running instances एक साथ बदलें"], ["Disable monitoring during deployment", "Deployment के दौरान monitoring बंद करें"], ["Remove the previous release before checking compatibility", "Compatibility जाँचने से पहले पुराना release हटाएँ"]], 0, "Staged rollout, monitoring and rollback help reveal incompatibilities before they affect the whole deployment.", "Staged rollout, monitoring और rollback पूरे deployment पर असर से पहले incompatibility पहचानने में मदद करते हैं।", "Expected Practice"),
        q("iot-platforms", "Hard", "A device sends measurements through a gateway to a cloud rule engine and then to a dashboard. The graph is delayed, but the rule engine records events promptly. Where should investigation focus first?", "Device gateway से cloud rule engine और फिर dashboard तक measurements भेजता है। Graph देर से अपडेट होता है लेकिन rule engine events तुरंत record करता है। जाँच पहले कहाँ केंद्रित हो?", [["The dashboard's query, refresh interval and presentation cache after confirming stored event timestamps", "Stored event timestamps की पुष्टि के बाद dashboard की query, refresh interval और presentation cache"], ["The sensor's calibration immediately", "तुरंत sensor calibration पर"], ["The device's physical enclosure", "Device के physical enclosure पर"], ["The gateway's radio channel despite prompt rule ingestion", "Prompt rule ingestion के बावजूद gateway radio channel पर"]], 0, "Prompt ingestion and rule processing indicate the delay is downstream in querying or presenting the stored data.", "Prompt ingestion और rule processing बताते हैं कि देरी stored data की querying या presentation में downstream है।", "Expected Practice"),

        q("iot-security", "Moderate", "An IoT device connects to a server over TLS. Which client check is necessary to avoid trusting an impostor server?", "IoT device TLS पर server से जुड़ता है। Impostor server पर भरोसा करने से बचने के लिए client को क्या जाँचना चाहिए?", [["Validate the server certificate chain and intended server identity", "Server certificate chain और intended server identity validate करें"], ["Accept every certificate without inspection", "जाँच के बिना हर certificate स्वीकार करें"], ["Check only the server's display color", "केवल server का display color जाँचें"], ["Disable encryption after the first connection", "पहले connection के बाद encryption बंद करें"]], 0, "TLS protects a connection only when the peer's certificate and identity are correctly verified.", "TLS connection तभी सुरक्षित करता है जब peer का certificate और identity सही ढंग से verify हों।", "Expected Practice"),
        q("iot-security", "Moderate", "A lighting controller should change lights but must not access health-monitoring records on the same platform. Which access-control principle applies?", "Lighting controller को lights बदलनी चाहिए लेकिन उसी platform के health-monitoring records तक पहुँच नहीं होनी चाहिए। कौन-सा access-control principle लागू होता है?", [["Grant the least privilege required for its assigned function", "Assigned function के लिए आवश्यक न्यूनतम privilege दें"], ["Give every device administrator rights", "हर device को administrator rights दें"], ["Share one unrestricted account across services", "सभी services में एक unrestricted account साझा करें"], ["Disable authorization for internal traffic", "Internal traffic के लिए authorization बंद करें"]], 0, "Least privilege confines each identity to the data and actions needed for its role.", "Least privilege हर identity को उसकी भूमिका के लिए आवश्यक data और actions तक सीमित करता है।", "Expected Practice"),
        q("iot-security", "Moderate", "A home camera stores recordings on its device. Which measure best reduces exposure if the storage is removed or accessed without permission?", "Home camera recordings अपने device पर रखता है। Storage निकाल लिया जाए या बिना अनुमति access हो तो exposure घटाने के लिए कौन-सा उपाय बेहतर है?", [["Encrypt stored data and protect the keys with appropriate device controls", "Stored data encrypt करें और keys को उपयुक्त device controls से सुरक्षित रखें"], ["Name the files with shorter names", "Files के नाम छोटे रखें"], ["Use encryption only for the Wi-Fi network, not stored files", "केवल Wi-Fi encrypt करें, stored files नहीं"], ["Make recordings readable to every local account", "Recordings हर local account के लिए readable बनाएँ"]], 0, "Encryption at rest reduces the usefulness of exposed storage when key handling is also protected.", "Key handling भी सुरक्षित हो तो encryption at rest उजागर storage के उपयोग को सीमित करता है।", "Expected Practice"),
        q("iot-security", "Moderate", "A maintenance technician needs temporary access to diagnose a device. Which approach best limits unnecessary access afterward?", "Maintenance technician को device diagnose करने के लिए अस्थायी access चाहिए। बाद में अनावश्यक access सीमित करने का बेहतर तरीका क्या है?", [["Issue a scoped, time-limited account and revoke it when the task ends", "सीमित scope और अवधि वाला account दें और काम खत्म होने पर revoke करें"], ["Create a permanent shared administrator password", "स्थायी साझा administrator password बनाएँ"], ["Publish the credential in a public maintenance log", "Credential को public maintenance log में डालें"], ["Disable audit records during the visit", "Visit के दौरान audit records बंद करें"]], 0, "Temporary, scoped access limits privilege duration and supports accountability.", "अस्थायी, scoped access privilege की अवधि सीमित करता है और accountability में मदद करता है।", "Expected Practice"),
        q("iot-security", "Moderate", "A connected health sensor sends personal readings for analysis. Which data-handling practice reduces privacy risk while preserving the service purpose?", "Connected health sensor व्यक्तिगत readings analysis के लिए भेजता है। Service उद्देश्य बनाए रखते हुए कौन-सी data-handling practice privacy risk घटाती है?", [["Collect and retain only the fields and duration required, with access restricted to authorized roles", "केवल आवश्यक fields और अवधि तक data लें और authorized roles तक access सीमित रखें"], ["Retain all raw data indefinitely for any future purpose", "किसी भी भविष्य के उद्देश्य के लिए सारा raw data अनिश्चितकाल तक रखें"], ["Publish identifiable readings to simplify analytics", "Analytics सरल करने के लिए पहचान योग्य readings प्रकाशित करें"], ["Share credentials among all application users", "सभी application users में credentials साझा करें"]], 0, "Data minimization, retention limits and role-based access reduce exposure without abandoning the stated purpose.", "Data minimization, retention limits और role-based access बताए उद्देश्य को छोड़े बिना exposure घटाते हैं।", "Expected Practice"),
        q("iot-security", "Hard", "A device accepts signed firmware, but its boot process can still start an unsigned older image after a reset. Which additional mechanism best addresses this gap?", "Device signed firmware स्वीकार करता है, लेकिन reset के बाद boot process unsigned पुराना image चला सकता है। इस कमी को कौन-सा अतिरिक्त mechanism बेहतर हल करता है?", [["Secure boot that verifies each boot stage and enforces an approved image policy", "Secure boot जो हर boot stage verify करे और approved image policy लागू करे"], ["A longer network password", "लंबा network password"], ["A cloud dashboard with no boot verification", "Boot verification के बिना cloud dashboard"], ["A larger telemetry buffer", "बड़ा telemetry buffer"]], 0, "Secure boot checks software integrity before execution and can prevent unauthorized images from running.", "Secure boot execution से पहले software integrity जाँचता है और unauthorized images चलने से रोक सकता है।", "Expected Practice"),
        q("iot-security", "Hard", "A fleet detects unusual outbound traffic from one device. Which response best combines containment with evidence for investigation?", "Fleet एक device से unusual outbound traffic पहचानती है। Investigation के लिए containment और evidence को कौन-सा response बेहतर जोड़ता है?", [["Isolate the device or restrict its network path, preserve relevant logs and investigate its credentials and software state", "Device isolate करें या network path सीमित करें, relevant logs सुरक्षित रखें और credentials तथा software state जाँचें"], ["Delete all logs and leave the device fully connected", "सभी logs मिटाकर device पूरी तरह connected छोड़ दें"], ["Disable fleet monitoring to stop notifications", "Notifications रोकने के लिए fleet monitoring बंद करें"], ["Reinstall firmware without recording the incident", "Incident दर्ज किए बिना firmware reinstall करें"]], 0, "Containment limits ongoing communication while retained logs support a reasoned incident investigation.", "Containment चल रहे communication को सीमित करता है और सुरक्षित logs उचित incident investigation में मदद करते हैं।", "Expected Practice"),
        q("iot-security", "Hard", "A vendor plans support for an IoT product that will be deployed for ten years. Which lifecycle plan best reduces long-term security exposure?", "Vendor दस वर्षों तक deploy रहने वाले IoT product के support की योजना बनाता है। कौन-सी lifecycle योजना दीर्घकालिक security exposure बेहतर घटाती है?", [["Define a supported update period, vulnerability reporting path, signed patch process and end-of-support handling", "Supported update अवधि, vulnerability reporting मार्ग, signed patch process और end-of-support handling तय करें"], ["Ship once and leave exposed services unchanged indefinitely", "एक बार ship करके exposed services को अनिश्चितकाल तक अपरिवर्तित छोड़ें"], ["Rely on customers to discover every vulnerability themselves", "हर vulnerability खोजने के लिए केवल ग्राहकों पर निर्भर रहें"], ["Promise updates without provisioning an authenticated installation path", "Authenticated installation path बनाए बिना updates का वादा करें"]], 0, "Lifecycle security needs a realistic support window, reporting channel, trusted patch delivery and safe retirement or isolation guidance.", "Lifecycle security के लिए वास्तविक support अवधि, reporting channel, trusted patch delivery और सुरक्षित retirement या isolation guidance आवश्यक है।", "Expected Practice"),

        q("iot-applications", "Moderate", "A traffic system adjusts signal timing using measurements from connected road sensors. Which benefit is a direct IoT application outcome?", "Traffic system connected road sensors की measurements से signal timing बदलता है। कौन-सा लाभ IoT application का सीधा परिणाम है?", [["Responsive infrastructure control based on current conditions", "वर्तमान परिस्थितियों पर आधारित responsive infrastructure control"], ["Guaranteed elimination of all traffic", "सभी traffic का समाप्त होना सुनिश्चित करना"], ["Removal of the need for road safety rules", "Road safety rules की आवश्यकता समाप्त करना"], ["Automatic identification of every driver without consent", "बिना सहमति हर driver की पहचान स्वतः करना"]], 0, "Connected sensing can let infrastructure adapt its operation to current observed conditions.", "Connected sensing infrastructure को वर्तमान देखी गई स्थितियों के अनुसार संचालन बदलने देती है।", "Expected Practice"),
        q("iot-applications", "Moderate", "A factory uses vibration trends to schedule inspection before a motor fails. Which application approach does this represent?", "Factory motor fail होने से पहले inspection schedule करने के लिए vibration trends उपयोग करती है। यह कौन-सा application approach है?", [["Condition monitoring supporting predictive maintenance", "Predictive maintenance में मदद करने वाला condition monitoring"], ["One-time manual device naming", "एक बार का manual device naming"], ["Unconditional actuator operation", "बिना शर्त actuator operation"], ["Public broadcasting of raw production data", "Raw production data का public broadcast"]], 0, "Trend-based condition monitoring can reveal deterioration and inform maintenance before a breakdown.", "Trend-आधारित condition monitoring खराबी पहचान सकता है और breakdown से पहले maintenance में मदद करता है।", "Expected Practice"),
        q("iot-applications", "Moderate", "A smart-home occupancy sensor should control lights without recording who entered a room. Which implementation best follows data minimization?", "Smart-home occupancy sensor को कमरे में कौन आया यह record किए बिना lights नियंत्रित करनी हैं। कौन-सा implementation data minimization का पालन करता है?", [["Process occupancy locally and transmit only the state needed for lighting control", "Occupancy local रूप से process करें और lighting control के लिए आवश्यक state ही भेजें"], ["Stream continuous identifiable video to an unrelated service", "Continuous identifiable video unrelated service को भेजें"], ["Store each visitor's identity indefinitely", "हर visitor की identity अनिश्चितकाल तक रखें"], ["Publish room occupancy to all nearby devices", "Room occupancy सभी आसपास के devices में publish करें"]], 0, "Local processing and minimal state transmission can provide automation without collecting unnecessary identity data.", "Local processing और न्यूनतम state transmission अनावश्यक identity data लिए बिना automation दे सकते हैं।", "Expected Practice"),
        q("iot-applications", "Moderate", "A water utility uses connected meters to find unusual night-time flow that may indicate a leak. What is the primary application function?", "Water utility संभावित leak पहचानने के लिए connected meters से रात के unusual flow का पता लगाती है। मुख्य application function क्या है?", [["Anomaly monitoring that prompts a targeted inspection", "लक्षित निरीक्षण शुरू करने वाली anomaly monitoring"], ["Replacing all pipes automatically from one reading", "एक reading से सभी pipes स्वतः बदलना"], ["Publishing customer consumption histories publicly", "Customer consumption histories सार्वजनिक करना"], ["Disabling meter timestamps", "Meter timestamps बंद करना"]], 0, "Unexpected consumption patterns can prioritize inspection, while a human or validated process confirms the cause.", "असामान्य consumption pattern निरीक्षण को प्राथमिकता दे सकता है; कारण की पुष्टि मानव या validated process करता है।", "Expected Practice"),
        q("iot-applications", "Moderate", "A connected medicine cabinet records that a dose compartment was opened but cannot confirm that medicine was taken. How should the application present this event?", "Connected medicine cabinet dose compartment खुलने का record रखता है लेकिन medicine लेने की पुष्टि नहीं कर सकता। Application को यह event कैसे दिखाना चाहिए?", [["As an opening event, clearly distinguishing it from confirmed ingestion", "Opening event के रूप में, इसे confirmed ingestion से स्पष्ट अलग रखते हुए"], ["As proof that the patient swallowed the medicine", "इस प्रमाण के रूप में कि patient ने medicine निगल ली"], ["As a diagnosis of the patient's condition", "Patient की स्थिति के diagnosis के रूप में"], ["As a reason to publish the patient's full record", "Patient का पूरा record प्रकाशित करने के कारण के रूप में"]], 0, "Responsible applications distinguish what a sensor actually observes from an inference it cannot establish.", "जिम्मेदार application sensor द्वारा वास्तव में देखी घटना को उस निष्कर्ष से अलग रखती है जिसे वह सिद्ध नहीं कर सकता।", "Expected Practice"),
        q("iot-applications", "Hard", "A smart-grid controller can reduce nonessential loads during a peak but must preserve power for critical medical equipment. Which application policy is most appropriate?", "Smart-grid controller peak के दौरान nonessential loads घटा सकता है लेकिन critical medical equipment की power बचानी है। कौन-सी application policy सबसे उपयुक्त है?", [["Use explicitly prioritized load classes, protected exceptions and human-reviewed emergency rules", "स्पष्ट priority वाले load classes, protected exceptions और human-reviewed emergency rules उपयोग करें"], ["Disconnect every load based only on total demand", "केवल total demand के आधार पर हर load disconnect करें"], ["Let each sensor independently switch critical circuits", "हर sensor को independently critical circuits switch करने दें"], ["Ignore safety constraints when the grid reaches a threshold", "Grid threshold पर पहुँचने पर safety constraints अनदेखा करें"]], 0, "Priority and protected exceptions balance demand response with safety-critical service requirements.", "Priority और protected exceptions demand response को safety-critical service आवश्यकताओं के साथ संतुलित करते हैं।", "Expected Practice"),
        q("iot-applications", "Hard", "A city is piloting connected parking sensors. Before scaling, which evaluation best tests whether the deployment delivers public value responsibly?", "City connected parking sensors का pilot कर रही है। Scale करने से पहले कौन-सा evaluation जाँचता है कि deployment जिम्मेदारी से public value देता है?", [["Measure accuracy, coverage, maintenance cost, accessibility and privacy impact against defined outcomes", "परिभाषित outcomes के विरुद्ध accuracy, coverage, maintenance cost, accessibility और privacy impact मापें"], ["Count installed devices only", "केवल लगाए गए devices गिनें"], ["Assume more collected data always improves service", "मान लें अधिक data हमेशा service सुधारता है"], ["Expand citywide before reviewing pilot results", "Pilot results देखे बिना पूरे शहर में विस्तार करें"]], 0, "A balanced pilot evaluation tests effectiveness, operational sustainability, inclusion and data consequences before wider deployment.", "संतुलित pilot evaluation बड़े deployment से पहले प्रभावशीलता, संचालन स्थिरता, समावेशन और data परिणाम जाँचता है।", "Expected Practice"),
        q("iot-applications", "Hard", "An industrial predictive-maintenance model reports a bearing failure risk, but the sensor is known to drift and false alarms cause costly shutdowns. What should the operator do before acting automatically?", "Industrial predictive-maintenance model bearing failure risk बताता है, लेकिन sensor drift करता है और false alarms महंगे shutdown कराते हैं। स्वतः कार्रवाई से पहले operator को क्या करना चाहिए?", [["Check sensor health and model confidence, corroborate with relevant signals and define a safe human escalation path", "Sensor health और model confidence जाँचें, संबंधित signals से पुष्टि करें और सुरक्षित human escalation path तय करें"], ["Shut down every machine on any single unverified alert", "किसी भी एक unverified alert पर हर machine बंद करें"], ["Ignore all alerts because sensors can drift", "Sensor drift कर सकते हैं इसलिए सभी alerts अनदेखा करें"], ["Remove the model's uncertainty information", "Model की uncertainty जानकारी हटा दें"]], 0, "Sensor quality, corroborating evidence and safe escalation reduce harm from uncertain automated predictions.", "Sensor quality, corroborating evidence और सुरक्षित escalation अनिश्चित automated predictions से होने वाले नुकसान घटाते हैं।", "Expected Practice")
    ];
}(window));
